solution.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] ruxsat = new int[n];
        for (int i = 0; i < n; i++) {
            ruxsat[i] = in.nextInt();
        }
        int m = in.nextInt();
        for (int i = 0; i < m; i++) {
            int q = in.nextInt();
            boolean bor = false;
            for (int p : ruxsat) {
                if (p == q) {
                    bor = true;
                }
            }
            System.out.println(bor ? "allow" : "deny");
        }
    }
}

solution.cpp:
#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int ruxsat[105];
    for (int i = 0; i < n; i++) {
        cin >> ruxsat[i];
    }
    int m;
    cin >> m;
    for (int i = 0; i < m; i++) {
        int q;
        cin >> q;
        bool bor = false;
        for (int j = 0; j < n; j++) {
            if (ruxsat[j] == q) {
                bor = true;
            }
        }
        cout << (bor ? "allow" : "deny") << endl;
    }
    return 0;
}
